CREATE TABLE Items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  value TEXT NOT NULL
);
CREATE TABLE ItemReceipts (
  actor TEXT NOT NULL,
  operation TEXT NOT NULL,
  key TEXT NOT NULL,
  digest TEXT NOT NULL,
  item_id INTEGER NOT NULL REFERENCES Items(id),
  PRIMARY KEY (actor, operation, key)
);

export class IdempotencyConflict extends Error {}

export async function createItem(
  db: Env['DB'], actor: string, key: string, value: string,
): Promise<number> {
  const session = db.withSession('first-primary');
  const bytes = new TextEncoder().encode(JSON.stringify({ value }));
  const hash = await crypto.subtle.digest('SHA-256', bytes);
  const digest = Array.from(new Uint8Array(hash), b => b.toString(16).padStart(2, '0')).join('');
  const operation = 'create-item:v1';
  const receipt = () => session.prepare(
    'SELECT digest, item_id FROM ItemReceipts WHERE actor = ? AND operation = ? AND key = ?',
  ).bind(actor, operation, key).first<{ digest: string; item_id: number }>();
  const recover = (row: { digest: string; item_id: number }) => {
    if (row.digest !== digest) throw new IdempotencyConflict('Key already used for different data');
    return row.item_id;
  };
  const prior = await receipt();
  if (prior) return recover(prior);
  try {
    const [created] = await session.batch<{ id: number }>([
      session.prepare('INSERT INTO Items (value) VALUES (?) RETURNING id').bind(value),
      session.prepare(
        'INSERT INTO ItemReceipts (actor, operation, key, digest, item_id) VALUES (?, ?, ?, ?, last_insert_rowid())',
      ).bind(actor, operation, key, digest),
    ]);
    return created.results[0].id;
  } catch (err) {
    console.error(err);
    const completed = await receipt();
    if (completed) return recover(completed);
    throw err;
  }
}
